def transform(grid):
    h, w = len(grid), len(grid[0])

    def runs(values):
        result = []
        i = 0
        while i < len(values):
            if values[i] == 0:
                i += 1
                continue
            j = i
            while j < len(values) and values[j] != 0:
                j += 1
            if j - i >= 3:
                result.append((i + j - 1) // 2)
            i = j
        return result

    def centers_from_lines(lines, length):
        line = max(lines, key=lambda a: sum(v != 0 for v in a))
        centers = runs(line)
        if not centers:
            return []
        if len(centers) >= 2:
            pitch = min(b - a for a, b in zip(centers, centers[1:]))
        else:
            return centers

        result = list(centers)
        while result[-1] + pitch < length:
            result.append(result[-1] + pitch)
        return result

    ys = centers_from_lines(grid, h)
    xs = centers_from_lines([list(col) for col in zip(*grid)], w)

    points = {}
    for y in ys:
        for x in xs:
            points.setdefault(grid[y][x], []).append((y, x))

    out = [row[:] for row in grid]

    def connect(a, b, color):
        y1, x1 = a
        y2, x2 = b
        if y1 == y2:
            for x in range(min(x1, x2) + 1, max(x1, x2)):
                if out[y1][x] == 0:
                    out[y1][x] = color
        elif x1 == x2:
            for y in range(min(y1, y2) + 1, max(y1, y2)):
                if out[y][x1] == 0:
                    out[y][x1] = color

    for color, coords in points.items():
        if color == 0 or len(coords) != 4:
            continue
        rows = {}
        cols = {}
        for y, x in coords:
            rows.setdefault(y, []).append(x)
            cols.setdefault(x, []).append(y)
        for y, xs_in_row in rows.items():
            xs_in_row.sort()
            for a, b in zip(xs_in_row, xs_in_row[1:]):
                connect((y, a), (y, b), color)
        for x, ys_in_col in cols.items():
            ys_in_col.sort()
            for a, b in zip(ys_in_col, ys_in_col[1:]):
                connect((a, x), (b, x), color)

    return out
