    if not counts:
        return out

    # Most frequent color is the repeated tile's frame.
    frame = counts.most_common(1)[0][0]
    inner_counts = Counter(
        v for row in grid for v in row if v != 0 and v != frame
    )
    if not inner_counts:
        return out

    # The most frequent interior color is the regular tile content.
    ordinary = inner_counts.most_common(1)[0][0]
    special_colors = set(inner_counts) - {ordinary}

    h, w = len(grid), len(grid[0])
